import Fastify, { type FastifyInstance, type FastifyServerOptions } from 'fastify';
import { pathToFileURL } from 'node:url';
import type { AdapterConfig } from './config/types.js';
import { loadConfiguration } from './config/loader.js';
import { getHealth, getReadiness } from './handlers/health.js';
import { createRoutingHandler } from './handlers/routing.handler.js';
import { setConfigValid, setConfigInvalid } from './config/state.js';
import { formatValidationError } from './handlers/error-formatter.js';
import { ValidationError, VALIDATION_ERROR_TYPES, isValidationError } from './types/validation-errors.js';

declare module 'fastify' {
  interface FastifyInstance {
    config: AdapterConfig;
  }
}

export type BuildServerOptions = {
  logger?: FastifyServerOptions['logger'];
  config?: AdapterConfig;
};

export function buildServer(options: BuildServerOptions = {}): FastifyInstance {
  const logger: FastifyServerOptions['logger'] =
    options.logger !== undefined
      ? options.logger
      : process.env.LOG_PRETTY === '1'
        ? {
            level: 'info',
            transport: {
              target: 'pino-pretty',
              options: {
                colorize: true
              }
            }
          }
        : {
            level: 'info'
          };

  const app = Fastify({
    logger,
    bodyLimit: options.config?.maxRequestSizeBytes
  });

  if (options.config) {
    app.decorate('config', options.config);
  }

  // Register error handler for validation errors
  app.setErrorHandler((error, request, reply) => {
    if (isValidationError(error)) {
      return reply.status(400).send(formatValidationError(error, request.id));
    }

    if (
      app.config &&
      typeof error === 'object' &&
      error !== null &&
      'code' in error &&
      error.code === 'FST_ERR_CTP_BODY_TOO_LARGE'
    ) {
      const maxRequestSizeMB = Math.round(app.config.maxRequestSizeBytes / (1024 * 1024));
      const validationError = new ValidationError(
        VALIDATION_ERROR_TYPES.PAYLOAD_TOO_LARGE,
        `Request payload exceeds maximum size of ${maxRequestSizeMB}MB`
      );

      return reply.status(400).send(formatValidationError(validationError, request.id));
    }

    // Let other errors be handled by default handler
    throw error;
  });
  let activeConnections = 0;
  const maxConnections = options.config?.maxConcurrentConnections ?? 1000;

  // Register hook to track connections and enforce limit
  app.addHook('onRequest', async (request, _reply) => {
    // Health and readiness endpoints bypass connection limit
    if (request.url === '/health' || request.url === '/ready') {
      return;
    }

    activeConnections++;

    if (activeConnections > maxConnections) {
      activeConnections--;
      void _reply.code(503).send({
        error: 'Service Unavailable',
        message: 'Maximum concurrent connections exceeded',
        requestId: request.id
      });
      return;
    }
  });

  // Register hook to decrement connection count on response
  app.addHook('onResponse', async (request, _reply) => {
    if (request.url !== '/health' && request.url !== '/ready') {
      activeConnections--;
    }
  });

  // Register hook to exclude health/readiness from request logging
  // These endpoints are called frequently by orchestration platforms
  // and shouldn't clutter application logs
  app.addHook('onRequest', async (request, _reply) => {
    if (request.url === '/health' || request.url === '/ready') {
      request.log.level = 'silent';
    }
  });

  // Health endpoint - Kubernetes liveness probe
  // Always returns 200 if process is alive
  app.get('/health', getHealth);

  // Readiness endpoint - Kubernetes readiness probe
  // Returns 200 if ready to accept traffic, 503 otherwise
  app.get('/ready', getReadiness);

  // Register API endpoints with routing handler (if config is available)
  if (app.config) {
    const routingHandler = createRoutingHandler(app.config);
    app.post('/v1/responses', routingHandler);
    app.post('/v1/chat/completions', routingHandler);
  }

  return app;
}

export async function startServer(): Promise<void> {
  try {
    // Load and validate configuration
    const config = await loadConfiguration();
    
    console.log(JSON.stringify({ 
      level: 'info',
      msg: 'Configuration loaded successfully',
      targetUrl: config.targetUrl,
      modelCount: Object.keys(config.modelMapping).length,
      upstreamTimeoutSeconds: config.upstreamTimeoutSeconds,
      maxConcurrentConnections: config.maxConcurrentConnections,
      maxRequestSizeBytes: config.maxRequestSizeBytes,
      maxJsonDepth: config.maxJsonDepth
    }));

    // Set global config state to valid for readiness handler
    setConfigValid(config as unknown as Record<string, unknown>);

    const app = buildServer({ config });

    const port = Number.parseInt(process.env.PORT ?? '3000', 10);

    await app.listen({ port, host: '0.0.0.0' });
    app.log.info({ action: 'server_started', port });
  } catch (error) {
    // Set global config state to invalid for readiness handler
    setConfigInvalid(error instanceof Error ? error : new Error(String(error)));

    console.error(JSON.stringify({
      level: 'error',
      msg: 'Configuration validation failed',
      error: error instanceof Error ? error.message : String(error),
      action: 'server_start_failed'
    }));
    process.exit(1);
  }
}

const entryFile = process.argv[1];
if (entryFile) {
  const isMain = import.meta.url === pathToFileURL(entryFile).href;
  if (isMain) {
    void startServer();
  }
}

import type { ApiType } from '../config/types.js';
import { ModelMapper } from './model-mapper.js';
import { ValidationError, VALIDATION_ERROR_TYPES } from '../types/validation-errors.js';

export type RoutingDecision = 'pass-through' | 'translate';

export interface RoutingResult {
  decision: RoutingDecision;
  sourceFormat: ApiType;
  targetFormat: ApiType;
  model: string;
}

/**
 * Router - Determines routing path for requests
 * Detects if source format matches target format (pass-through) or needs translation
 */
export class Router {
  constructor(private readonly modelMapper: ModelMapper) {}

  /**
   * Detect source API format from endpoint path
   * @param path The HTTP request path
   * @returns The source API type
   * @throws Error if endpoint is not recognized
   */
  detectSourceFormat(path: string): ApiType {
    if (path.includes('/v1/responses')) {
      return 'response';
    }
    
    if (path.includes('/v1/chat/completions')) {
      return 'chat_completions';
    }
    
    throw new Error(`Unknown endpoint: ${path}`);
  }

  /**
   * Extract model name from request body
   * Works for both response and chat_completions formats
   * Both formats have model at request.body.model
   * @param body The request body
   * @returns The model name
   * @throws Error if model field is missing or invalid
   */
  extractModel(body: unknown): string {
    const invalidModelMessage = 'Model field is required and must be a non-empty string';

    if (typeof body !== 'object' || body === null) {
      throw new ValidationError(
        VALIDATION_ERROR_TYPES.INVALID_MODEL_FIELD,
        invalidModelMessage
      );
    }

    const bodyObj = body as Record<string, unknown>;
    const model = bodyObj.model;

    if (typeof model !== 'string' || model.length === 0) {
      throw new ValidationError(
        VALIDATION_ERROR_TYPES.INVALID_MODEL_FIELD,
        invalidModelMessage
      );
    }

    return model;
  }

  /**
   * Validate that a model exists in the mapping
   * @param model The model name to validate
   * @throws ValidationError if model is not in mapping
   */
  validateModel(model: string): void {
    if (!this.modelMapper.hasModel(model)) {
      throw new ValidationError(
        VALIDATION_ERROR_TYPES.UNKNOWN_MODEL,
        `Model '${model}' not found in configuration`
      );
    }
  }

  /**
   * Make routing decision for a request
   * @param path The HTTP request path
   * @param body The request body
   * @returns Routing result with decision and details
   * @throws Error if routing cannot be determined (invalid input)
   * @throws ValidationError if model is not in mapping
   */
  routingDecision(path: string, body: unknown): RoutingResult {
    // Detect source format from endpoint
    const sourceFormat = this.detectSourceFormat(path);

    // Extract model from body
    const model = this.extractModel(body);

    // Validate that model exists in mapping
    this.validateModel(model);

    // Look up target format for this model
    const targetFormat = this.modelMapper.getTargetApi(model);

    // Determine routing path
    const decision: RoutingDecision =
      sourceFormat === targetFormat ? 'pass-through' : 'translate';

    return {
      decision,
      sourceFormat,
      targetFormat,
      model
    };
  }
}

import { describe, it, expect } from 'vitest';
import { Router } from '../../../src/routing/router.js';
import { ModelMapper } from '../../../src/routing/model-mapper.js';
import type { ModelMapping } from '../../../src/config/types.js';
import { ValidationError, VALIDATION_ERROR_TYPES } from '../../../src/types/validation-errors.js';

describe('Router', () => {
  const testMapping: ModelMapping = {
    'gpt-4': 'response',
    'gpt-4-turbo': 'response',
    'gpt-3.5-turbo': 'chat_completions',
    'gpt-3.5-turbo-16k': 'chat_completions',
    'gpt-4o': 'response',
    'gpt-4o-mini': 'response'
  };

  const modelMapper = new ModelMapper(testMapping);
  const router = new Router(modelMapper);

  describe('detectSourceFormat', () => {
    it('should detect response format from /v1/responses path', () => {
      expect(router.detectSourceFormat('/v1/responses')).toBe('response');
    });

    it('should detect chat_completions format from /v1/chat/completions path', () => {
      expect(router.detectSourceFormat('/v1/chat/completions')).toBe('chat_completions');
    });

    it('should handle paths with query parameters', () => {
      expect(router.detectSourceFormat('/v1/responses?timeout=30')).toBe('response');
      expect(router.detectSourceFormat('/v1/chat/completions?stream=true')).toBe('chat_completions');
    });

    it('should throw for unknown endpoint', () => {
      expect(() => router.detectSourceFormat('/v1/unknown')).toThrow(
        'Unknown endpoint: /v1/unknown'
      );
    });

    it('should throw for empty path', () => {
      expect(() => router.detectSourceFormat('')).toThrow(
        'Unknown endpoint: '
      );
    });
  });

  describe('extractModel', () => {
    it('should extract model from response format body', () => {
      const body = {
        model: 'gpt-4',
        messages: []
      };
      expect(router.extractModel(body)).toBe('gpt-4');
    });

    it('should extract model from chat_completions format body', () => {
      const body = {
        model: 'gpt-3.5-turbo',
        messages: []
      };
      expect(router.extractModel(body)).toBe('gpt-3.5-turbo');
    });

    it('should extract model with hyphens and dots', () => {
      const body = { model: 'gpt-3.5-turbo-16k' };
      expect(router.extractModel(body)).toBe('gpt-3.5-turbo-16k');
    });

    it('should throw when body is null', () => {
      expect(() => router.extractModel(null)).toThrow(ValidationError);
    });

    it('should throw when body is not an object', () => {
      expect(() => router.extractModel('not-an-object')).toThrow(ValidationError);
      expect(() => router.extractModel(123)).toThrow(ValidationError);
      expect(() => router.extractModel([])).toThrow(ValidationError);
    });

    it('should throw when model field is missing', () => {
      expect(() => router.extractModel({})).toThrow(ValidationError);
    });

    it('should throw when model field is not a string', () => {
      expect(() => router.extractModel({ model: 123 })).toThrow(ValidationError);
      expect(() => router.extractModel({ model: null })).toThrow(ValidationError);
      expect(() => router.extractModel({ model: {} })).toThrow(ValidationError);
    });

    it('should throw when model field is empty string', () => {
      expect(() => router.extractModel({ model: '' })).toThrow(ValidationError);
    });

    it('should use invalid_model_field error type for invalid model', () => {
      try {
        router.extractModel({ model: '' });
        expect.fail('Should have thrown');
      } catch (error) {
        expect((error as ValidationError).type).toBe(VALIDATION_ERROR_TYPES.INVALID_MODEL_FIELD);
      }
    });
  });

  describe('validateModel', () => {
    it('should pass validation for known models', () => {
      expect(() => router.validateModel('gpt-4')).not.toThrow();
      expect(() => router.validateModel('gpt-3.5-turbo')).not.toThrow();
      expect(() => router.validateModel('gpt-4-turbo')).not.toThrow();
      expect(() => router.validateModel('gpt-3.5-turbo-16k')).not.toThrow();
      expect(() => router.validateModel('gpt-4o')).not.toThrow();
      expect(() => router.validateModel('gpt-4o-mini')).not.toThrow();
    });

    it('should throw ValidationError for unknown models', () => {
      expect(() => router.validateModel('unknown-model')).toThrow(
        ValidationError
      );
    });

    it('should include model name in error message', () => {
      try {
        router.validateModel('unknown-model');
        expect.fail('Should have thrown');
      } catch (error) {
        expect((error as ValidationError).message).toContain('unknown-model');
      }
    });

    it('should use correct error type', () => {
      try {
        router.validateModel('not-found');
        expect.fail('Should have thrown');
      } catch (error) {
        expect((error as ValidationError).type).toBe(VALIDATION_ERROR_TYPES.UNKNOWN_MODEL);
      }
    });

    it('should have adapter_error source', () => {
      try {
        router.validateModel('missing');
        expect.fail('Should have thrown');
      } catch (error) {
        expect((error as ValidationError).source).toBe('adapter_error');
      }
    });
  });

  describe('routingDecision', () => {
    describe('pass-through scenarios', () => {
      it('should route to pass-through when gpt-4 hits /v1/responses', () => {
        const body = { model: 'gpt-4' };
        const result = router.routingDecision('/v1/responses', body);

        expect(result.decision).toBe('pass-through');
        expect(result.sourceFormat).toBe('response');
        expect(result.targetFormat).toBe('response');
        expect(result.model).toBe('gpt-4');
      });

      it('should route to pass-through when gpt-3.5-turbo hits /v1/chat/completions', () => {
        const body = { model: 'gpt-3.5-turbo' };
        const result = router.routingDecision('/v1/chat/completions', body);

        expect(result.decision).toBe('pass-through');
        expect(result.sourceFormat).toBe('chat_completions');
        expect(result.targetFormat).toBe('chat_completions');
        expect(result.model).toBe('gpt-3.5-turbo');
      });

      it('should route gpt-4-turbo to pass-through at /v1/responses', () => {
        const body = { model: 'gpt-4-turbo' };
        const result = router.routingDecision('/v1/responses', body);

        expect(result.decision).toBe('pass-through');
        expect(result.sourceFormat).toBe('response');
        expect(result.targetFormat).toBe('response');
      });

      it('should route gpt-4o to pass-through at /v1/responses', () => {
        const body = { model: 'gpt-4o' };
        const result = router.routingDecision('/v1/responses', body);

        expect(result.decision).toBe('pass-through');
        expect(result.sourceFormat).toBe('response');
        expect(result.targetFormat).toBe('response');
      });

      it('should route gpt-4o-mini to pass-through at /v1/responses', () => {
        const body = { model: 'gpt-4o-mini' };
        const result = router.routingDecision('/v1/responses', body);

        expect(result.decision).toBe('pass-through');
        expect(result.sourceFormat).toBe('response');
        expect(result.targetFormat).toBe('response');
      });

      it('should route gpt-3.5-turbo-16k to pass-through at /v1/chat/completions', () => {
        const body = { model: 'gpt-3.5-turbo-16k' };
        const result = router.routingDecision('/v1/chat/completions', body);

        expect(result.decision).toBe('pass-through');
        expect(result.sourceFormat).toBe('chat_completions');
        expect(result.targetFormat).toBe('chat_completions');
      });
    });

    describe('translation scenarios', () => {
      it('should route to translate when gpt-3.5-turbo hits /v1/responses', () => {
        const body = { model: 'gpt-3.5-turbo' };
        const result = router.routingDecision('/v1/responses', body);

        expect(result.decision).toBe('translate');
        expect(result.sourceFormat).toBe('response');
        expect(result.targetFormat).toBe('chat_completions');
        expect(result.model).toBe('gpt-3.5-turbo');
      });

      it('should route to translate when gpt-4 hits /v1/chat/completions', () => {
        const body = { model: 'gpt-4' };
        const result = router.routingDecision('/v1/chat/completions', body);

        expect(result.decision).toBe('translate');
        expect(result.sourceFormat).toBe('chat_completions');
        expect(result.targetFormat).toBe('response');
        expect(result.model).toBe('gpt-4');
      });

      it('should route to translate when gpt-4-turbo hits /v1/chat/completions', () => {
        const body = { model: 'gpt-4-turbo' };
        const result = router.routingDecision('/v1/chat/completions', body);

        expect(result.decision).toBe('translate');
        expect(result.sourceFormat).toBe('chat_completions');
        expect(result.targetFormat).toBe('response');
      });

      it('should route to translate when gpt-3.5-turbo-16k hits /v1/responses', () => {
        const body = { model: 'gpt-3.5-turbo-16k' };
        const result = router.routingDecision('/v1/responses', body);

        expect(result.decision).toBe('translate');
        expect(result.sourceFormat).toBe('response');
        expect(result.targetFormat).toBe('chat_completions');
      });

      it('should route to translate when gpt-4o hits /v1/chat/completions', () => {
        const body = { model: 'gpt-4o' };
        const result = router.routingDecision('/v1/chat/completions', body);

        expect(result.decision).toBe('translate');
        expect(result.sourceFormat).toBe('chat_completions');
        expect(result.targetFormat).toBe('response');
      });
    });

    describe('error scenarios', () => {
      it('should throw ValidationError when model not in mapping', () => {
        const body = { model: 'unknown-model' };
        expect(() => router.routingDecision('/v1/responses', body)).toThrow(
          ValidationError
        );
      });

      it('should use correct validation error type', () => {
        const body = { model: 'unknown-model' };
        try {
          router.routingDecision('/v1/responses', body);
          expect.fail('Should have thrown');
        } catch (error) {
          expect((error as ValidationError).type).toBe(VALIDATION_ERROR_TYPES.UNKNOWN_MODEL);
        }
      });

      it('should throw when endpoint is invalid', () => {
        const body = { model: 'gpt-4' };
        expect(() => router.routingDecision('/v1/invalid', body)).toThrow(
          'Unknown endpoint: /v1/invalid'
        );
      });

      it('should throw when body is invalid', () => {
        expect(() => router.routingDecision('/v1/responses', null)).toThrow(
          'Request body must be an object'
        );
        
        expect(() => router.routingDecision('/v1/responses', {})).toThrow(
          'Model field must be a non-empty string'
        );
      });
    });

    describe('edge cases', () => {
      it('should work with endpoints that have query parameters', () => {
        const body = { model: 'gpt-4' };
        const result = router.routingDecision('/v1/responses?timeout=30', body);

        expect(result.decision).toBe('pass-through');
        expect(result.sourceFormat).toBe('response');
      });

      it('should preserve complete request body structure', () => {
        const body = {
          model: 'gpt-4',
          messages: [
            { role: 'user', content: 'Hello' }
          ],
          temperature: 0.7,
          max_tokens: 100
        };
        const result = router.routingDecision('/v1/responses', body);

        expect(result.decision).toBe('pass-through');
        expect(result.model).toBe('gpt-4');
      });
    });
  });
});

import { describe, it, expect } from 'vitest';
import Fastify from 'fastify';
import { buildServer } from '../../src/index.js';
import { createRoutingHandler } from '../../src/handlers/routing.handler.js';
import { ModelMapper } from '../../src/routing/model-mapper.js';
import type { AdapterConfig } from '../../src/config/types.js';

describe('Validation Integration - Full Flow', () => {
  const testModelMapping = {
    'gpt-4': 'response',
    'gpt-4-turbo': 'response',
    'gpt-3.5-turbo': 'chat_completions',
    'gpt-3.5-turbo-16k': 'chat_completions',
    'gpt-4o': 'response',
    'gpt-4o-mini': 'response'
  };

  const testConfig: AdapterConfig = {
    targetUrl: 'http://localhost:3000',
    modelMappingFile: './config/model-mapping.json',
    modelMapping: testModelMapping,
    upstreamTimeoutSeconds: 60,
    maxConcurrentConnections: 1000,
    maxRequestSizeBytes: 10 * 1024 * 1024, // 10MB
    maxJsonDepth: 100
  };

  describe('Validation error responses', () => {
    it('should return correct error format for unknown model', async () => {
      const fastify = Fastify({ logger: false });
      const handler = createRoutingHandler(testConfig);
      
      fastify.post('/v1/responses', handler);

      const response = await fastify.inject({
        method: 'POST',
        url: '/v1/responses',
        payload: {
          model: 'unknown-model',
          messages: []
        }
      });

      expect(response.statusCode).toBe(400);
      const body = JSON.parse(response.body);
      expect(body).toHaveProperty('error');
      expect(body.error).toHaveProperty('type');
      expect(body.error).toHaveProperty('message');
      expect(body.error).toHaveProperty('source');
      expect(body).toHaveProperty('requestId');
      expect(body.error.type).toBe('unknown_model');
      expect(body.error.source).toBe('adapter_error');
    });

    it('should return invalid_model_field when model is missing', async () => {
      const fastify = Fastify({ logger: false });
      const handler = createRoutingHandler(testConfig);

      fastify.post('/v1/responses', handler);

      const response = await fastify.inject({
        method: 'POST',
        url: '/v1/responses',
        payload: {
          messages: []
        }
      });

      expect(response.statusCode).toBe(400);
      const body = JSON.parse(response.body);
      expect(body.error.type).toBe('invalid_model_field');
      expect(body.error.source).toBe('adapter_error');
    });

    it('should include model name in unknown model error message', async () => {
      const fastify = Fastify({ logger: false });
      const handler = createRoutingHandler(testConfig);
      
      fastify.post('/v1/responses', handler);

      const response = await fastify.inject({
        method: 'POST',
        url: '/v1/responses',
        payload: {
          model: 'gpt-99',
          messages: []
        }
      });

      const body = JSON.parse(response.body);
      expect(body.error.message).toContain('gpt-99');
    });
  });

  describe('Valid requests pass through validation', () => {
    it('should accept known models without validation errors', async () => {
      const fastify = Fastify({ logger: false });
      const handler = createRoutingHandler(testConfig);
      
      fastify.post('/v1/responses', handler);

      const response = await fastify.inject({
        method: 'POST',
        url: '/v1/responses',
        payload: {
          model: 'gpt-4',
          messages: []
        }
      });

      // Should NOT be a validation error (may be 501 for translation not implemented)
      expect(response.statusCode).not.toBe(400);
    });

    it('should accept chat/completions with valid model', async () => {
      const fastify = Fastify({ logger: false });
      const handler = createRoutingHandler(testConfig);
      
      fastify.post('/v1/chat/completions', handler);

      const response = await fastify.inject({
        method: 'POST',
        url: '/v1/chat/completions',
        payload: {
          model: 'gpt-3.5-turbo',
          messages: [{ role: 'user', content: 'hello' }]
        }
      });

      expect(response.statusCode).not.toBe(400);
    });
  });

  describe('JSON depth validation in routing context', () => {
    it('should reject deeply nested JSON', async () => {
      const fastify = Fastify({ logger: false });
      
      // Create config with small depth limit for testing
      const smallDepthConfig: AdapterConfig = {
        ...testConfig,
        maxJsonDepth: 3
      };
      
      const handler = createRoutingHandler(smallDepthConfig);
      fastify.post('/v1/responses', handler);

      // Create deeply nested JSON (depth > 3)
      const deepPayload = {
        model: 'gpt-4',
        a: {
          b: {
            c: {
              d: 'too deep'
            }
          }
        }
      };

      const response = await fastify.inject({
        method: 'POST',
        url: '/v1/responses',
        payload: deepPayload
      });

      expect(response.statusCode).toBe(400);
      const body = JSON.parse(response.body);
      expect(body.error.type).toBe('json_depth_exceeded');
    });

    it('should accept JSON within depth limit', async () => {
      const fastify = Fastify({ logger: false });
      
      const smallDepthConfig: AdapterConfig = {
        ...testConfig,
        maxJsonDepth: 5
      };
      
      const handler = createRoutingHandler(smallDepthConfig);
      fastify.post('/v1/responses', handler);

      // Create JSON with depth = 4 (within limit of 5)
      const validPayload = {
        model: 'gpt-4',
        a: {
          b: {
            c: {
              d: 'within limit'
            }
          }
        }
      };

      const response = await fastify.inject({
        method: 'POST',
        url: '/v1/responses',
        payload: validPayload
      });

      expect(response.statusCode).not.toBe(400);
    });
  });

  describe('Validation response structure', () => {
    it('should include requestId in validation error response', async () => {
      const fastify = Fastify({ logger: false });
      const handler = createRoutingHandler(testConfig);
      
      fastify.post('/v1/responses', handler);

      const response = await fastify.inject({
        method: 'POST',
        url: '/v1/responses',
        payload: {
          model: 'not-found-model',
          messages: []
        }
      });

      const body = JSON.parse(response.body);
      expect(body).toHaveProperty('requestId');
      expect(typeof body.requestId).toBe('string');
      expect(body.requestId.length).toBeGreaterThan(0);
    });

    it('should return consistent JSON structure for all error types', async () => {
      const fastify = Fastify({ logger: false });
      
      const smallDepthConfig: AdapterConfig = {
        ...testConfig,
        maxJsonDepth: 1
      };
      
      const handler = createRoutingHandler(smallDepthConfig);
      fastify.post('/v1/responses', handler);

      const responseDepthError = await fastify.inject({
        method: 'POST',
        url: '/v1/responses',
        payload: {
          model: 'gpt-4',
          a: { b: 'too deep' }
        }
      });

      const bodyDepth = JSON.parse(responseDepthError.body);
      
      // Check error structure
      expect(bodyDepth).toHaveProperty('error.type');
      expect(bodyDepth).toHaveProperty('error.message');
      expect(bodyDepth).toHaveProperty('error.source');
      expect(bodyDepth).toHaveProperty('requestId');

      // Check types
      expect(typeof bodyDepth.error.type).toBe('string');
      expect(typeof bodyDepth.error.message).toBe('string');
      expect(typeof bodyDepth.error.source).toBe('string');
      expect(typeof bodyDepth.requestId).toBe('string');
    });
  });

  describe('Multiple validation layers', () => {
    it('should catch unknown model even with valid depth', async () => {
      const fastify = Fastify({ logger: false });
      const handler = createRoutingHandler(testConfig);
      
      fastify.post('/v1/responses', handler);

      const response = await fastify.inject({
        method: 'POST',
        url: '/v1/responses',
        payload: {
          model: 'unknown-model',
          data: {
            nested: {
              structure: {
                here: 'value'
              }
            }
          }
        }
      });

      expect(response.statusCode).toBe(400);
      const body = JSON.parse(response.body);
      expect(body.error.type).toBe('unknown_model');
    });

    it('should validate depth before checking model in large payloads', async () => {
      const fastify = Fastify({ logger: false });
      
      const smallDepthConfig: AdapterConfig = {
        ...testConfig,
        maxJsonDepth: 2
      };
      
      const handler = createRoutingHandler(smallDepthConfig);
      fastify.post('/v1/responses', handler);

      // Both depth and model invalid - depth should trigger first
      const response = await fastify.inject({
        method: 'POST',
